EventGhost.PythonScript(u'import urllib2
import time

# Send heartbeat to HE. Optional event payload is # of retries in [2,20] if fail.

MIN_RETRIES = 2
MAX_RETRIES = 20

# payload, if present, is expected to be an integer between 2 and 20.
def extract_retries_override(payload, default=1):
 if not payload:
 return default

 try:
 retries = int(payload)
 except (ValueError, TypeError):
 eg.PrintWarningNotice(u"Couldn't parse retries from payload %r -- using default (%d)" % (payload, default))
 return default

 clamped = max(MIN_RETRIES, min(MAX_RETRIES, retries))
 if clamped != retries:
 eg.PrintWarningNotice(u"Retries value %d out of range -- clamped to %d" % (retries, clamped))
 return clamped

def send_heartbeat(retries=1, delay=2):
 url = eg.globals.target_url
 for attempt in range(1, retries + 1):
 try:
 urllib2.urlopen(url, timeout=5)
 eg.PrintDebugNotice(u"Heartbeat sent (attempt %d/%d)" % (attempt, retries))
 return True
 except Exception as e:
 eg.PrintError(u"Heartbeat attempt %d/%d failed: %s" % (attempt, retries, e))
 if attempt < retries:
 time.sleep(delay)
 eg.PrintError(u"Heartbeat failed after %d attempts -- giving up" % retries)
 return False

retries = extract_retries_override(eg.event.payload)
send_heartbeat(retries=retries)')
